(7651932, 1244907, 181847, '<td valign="top">Nice frost capture. Only closest leaf is totally in focus. Background seems noisy .</td>', 'Nice frost capture. Only closest leaf is totally in focus. Background seems noisy .', '2020-01-29 11:58:48.000000', NULL, 1),
(7651933, 1245242, 181847, '<td valign="top">Great job on what had to be a difficult shoot to capture</td>', 'Great job on what had to be a difficult shoot to capture', '2020-01-29 11:59:53.000000', NULL, 1),
