(7651936, 1244930, 181847, '<td valign="top">Well focused and exposed.</td>', 'Well focused and exposed.', '2020-01-29 12:01:40.000000', NULL, 1),
(7651937, 1245019, 181847, '<td valign="top">Extremely good DOF considering it is a night shoot. Sharp stars! Excellent shoot!</td>', 'Extremely good DOF considering it is a night shoot. Sharp stars! Excellent shoot!', '2020-01-29 12:03:50.000000', NULL, 1),
(7651939, 1245108, 181847, '<td valign="top">Eyes and face nicely focus. Bright areas in background a bit blown out.</td>', 'Eyes and face nicely focus. Bright areas in background a bit blown out.', '2020-01-29 12:05:26.000000', NULL, 1),
(7651941, 1244911, 181847, '<td valign="top">One of the nicest macro shoots I have see. Seems a bit too bright.</td>', 'One of the nicest macro shoots I have see. Seems a bit too bright.', '2020-01-29 12:07:53.000000', NULL, 1),
(7651943, 1245168, 181847, '<td valign="top">Good job on a difficult shoot. Like the shadows of the rock piles on the water. Sun and reflection a bit blown out but difficult to avoid and retain any definition on the dark side of the rock piles.</td>', 'Good job on a difficult shoot. Like the shadows of the rock piles on the water. Sun and reflection a bit blown out but difficult to avoid and retain any definition on the dark side of the rock piles.', '2020-01-29 12:12:22.000000', NULL, 1),
(7651944, 1244893, 181847, '<td valign="top">Good capture. Wish is was better focused.</td>', 'Good capture. Wish is was better focused.', '2020-01-29 12:14:26.000000', NULL, 1),
(7651946, 1244889, 181847, '<td valign="top">Good DOF and focus. Having shot from this exact spot in nearly same conditions I know how difficult it is to avoid over exposure of clouds and not have dark Pine Trees in foreground too dark.</td>', 'Good DOF and focus. Having shot from this exact spot in nearly same conditions I know how difficult it is to avoid over exposure of clouds and not have dark Pine Trees in foreground too dark.', '2020-01-29 12:18:56.000000', NULL, 1),
(7651947, 1245248, 181847, '<td valign="top">Great shoot!</td>', 'Great shoot!', '2020-01-29 12:19:50.000000', NULL, 1),
