(7651952, 1245329, 181847, '<td valign="top">Maybe a bit too much contrast.</td>', 'Maybe a bit too much contrast.', '2020-01-29 12:29:53.000000', NULL, 1),
(7651953, 1245125, 181847, '<td valign="top">Nice DOF. Halo at end of valley and mountain suggests HDR process a little over done.</td>', 'Nice DOF. Halo at end of valley and mountain suggests HDR process a little over done.', '2020-01-29 12:34:39.000000', NULL, 1),
(7651954, 1245020, 181847, '<td valign="top">Would love to see the color version.</td>', 'Would love to see the color version.', '2020-01-29 12:35:18.000000', NULL, 1),
