(7651980, 1245069, 113411, '<td valign="top">fabulous !!!</td>', 'fabulous !!!', '2020-01-29 14:34:50.000000', NULL, 1),
(7651992, 1245127, 61971, '<td valign="top">I like the artistic feel to this, but I would have liked it better without the dock in the middle, leaving just the ships. The lights being brighter on the dock/pier pull my eye from the part I love and feels more like the tall ships in your title.</td>', 'I like the artistic feel to this, but I would have liked it better without the dock in the middle, leaving just the ships. The lights being brighter on the dock/pier pull my eye from the part I love and feels more like the tall ships in your title.', '2020-01-29 20:29:07.000000', NULL, 1),
(7651993, 1245237, 61971, '<td valign="top">This is a beautiful area. The fence in the bottom pulls my eye away from the mountains though and is distracting.</td>', 'This is a beautiful area. The fence in the bottom pulls my eye away from the mountains though and is distracting.', '2020-01-29 20:30:04.000000', NULL, 1),
(7651994, 1244893, 61971, '<td valign="top">This is such a cool concept and timing. The bright oranges in the background are fighting for my attention with your subjects though. If you had a shorter depth of field to blur the background and then toned down the greens and oranges the subjects would pop more imo.</td>', 'This is such a cool concept and timing. The bright oranges in the background are fighting for my attention with your subjects though. If you had a shorter depth of field to blur the background and then toned down the greens and oranges the subjects would pop more imo.', '2020-01-29 20:35:56.000000', NULL, 1),
(7651995, 1245264, 61971, '<td valign="top">I feel like this is a cat under a Christmas tree, which can make for a great shot with some neat bokeh effects. I think you just needed a stronger light source to highlight Ray some more. imho</td>', 'I feel like this is a cat under a Christmas tree, which can make for a great shot with some neat bokeh effects. I think you just needed a stronger light source to highlight Ray some more. imho', '2020-01-29 20:44:58.000000', NULL, 1),
(7651996, 1244890, 61971, '<td valign="top">imo a bit dark in the photo and the subject. I feel like there is a story that you are trying to tell but I am just not really getting it other than it looks like a mom/grandma who has been murdered or by the positioning committed suicide.</td>', 'imo a bit dark in the photo and the subject. I feel like there is a story that you are trying to tell but I am just not really getting it other than it looks like a mom/grandma who has been murdered or by the positioning committed suicide.', '2020-01-29 20:51:08.000000', NULL, 1),
(7651997, 1245283, 61971, '<td valign="top">I like the contrasting subjects. imo could have used a crop off of the right side so the focus stays on the subjects.</td>', 'I like the contrasting subjects. imo could have used a crop off of the right side so the focus stays on the subjects.', '2020-01-29 20:53:37.000000', NULL, 1),
(7651998, 1244856, 61971, '<td valign="top">This is a cool subject piece. imo the background could be darkened a bit.</td>', 'This is a cool subject piece. imo the background could be darkened a bit.', '2020-01-29 20:55:00.000000', NULL, 1),
(7651999, 1245107, 61971, '<td valign="top">I like how the moon is playing peekaboo, I like how the water feels like a gradient going to the distance. There is a bit of lack of focus and overall noise that takes away from the shot though. imho</td>', 'I like how the moon is playing peekaboo, I like how the water feels like a gradient going to the distance. There is a bit of lack of focus and overall noise that takes away from the shot though. imho', '2020-01-29 21:06:03.000000', NULL, 1),
(7652000, 1245278, 61971, '<td valign="top">I love the textures in the books. imo the exposure could have been a little bit brighter.</td>', 'I love the textures in the books. imo the exposure could have been a little bit brighter.', '2020-01-29 21:10:40.000000', NULL, 1),
(7652001, 1245156, 61971, '<td valign="top">This looks like a beautiful spot. I keep wanting you to turn to the left though. There is a lot of noise on the tree side.</td>', 'This looks like a beautiful spot. I keep wanting you to turn to the left though. There is a lot of noise on the tree side.', '2020-01-29 21:19:56.000000', NULL, 1),
(7652002, 1245288, 61971, '<td valign="top">I like the lighting you have in this shot. I would like to see it without the smoke.</td>', 'I like the lighting you have in this shot. I would like to see it without the smoke.', '2020-01-29 21:24:50.000000', NULL, 1),
(7652003, 1244903, 61971, '<td valign="top">Really cool shot. imo better with a different angle you may have gotten some contrast between him and his background.</td>', 'Really cool shot. imo better with a different angle you may have gotten some contrast between him and his background.', '2020-01-29 21:29:24.000000', NULL, 1),
(7652010, 1244911, 23098, '<td valign="top">Peaceful and cool. Like the high key.</td>', 'Peaceful and cool. Like the high key.', '2020-01-29 23:16:30.000000', NULL, 1),
(7652011, 1244785, 23098, '<td valign="top">Great composition.</td>', 'Great composition.', '2020-01-29 23:17:15.000000', NULL, 1),
