(7652013, 1245114, 23098, '<td valign="top">A real personality...nice shot.</td>', 'A real personality...nice shot.', '2020-01-29 23:22:42.000000', NULL, 1),
(7652014, 1244859, 23098, '<td valign="top">Good composition and unique view of the cormorant.</td>', 'Good composition and unique view of the cormorant.', '2020-01-29 23:24:58.000000', NULL, 1),
