(7652166, 1245068, 61971, '<td valign="top">Great night shot. I love the composition and the drama that is in the clouds.</td>', 'Great night shot. I love the composition and the drama that is in the clouds.', '2020-01-30 16:20:13.000000', NULL, 1),
(7652167, 1244785, 86447, '<td valign="top">Those stars!  Wonderful image...  It''s like I''m there.</td>', 'Those stars!  Wonderful image...  It''s like I''m there.', '2020-01-30 16:20:18.000000', NULL, 1),
(7652168, 1244774, 86447, '<td valign="top">Gorgeous focus!</td>', 'Gorgeous focus!', '2020-01-30 16:20:45.000000', NULL, 1),
(7652169, 1245047, 86447, '<td valign="top">Love this of the Northern Lights!</td>', 'Love this of the Northern Lights!', '2020-01-30 16:21:13.000000', NULL, 1),
