(7652179, 1245298, 61971, '<td valign="top">He looks like he is doing a mating dance. Love it, great shot.</td>', 'He looks like he is doing a mating dance. Love it, great shot.', '2020-01-30 16:25:08.000000', NULL, 1),
(7652180, 1245129, 86447, '<td valign="top">Cute boys... lovely old prop, and...  it just makes me smile.</td>', 'Cute boys... lovely old prop, and...  it just makes me smile.', '2020-01-30 16:25:17.000000', NULL, 1),
